function teams_ok($value,string $message): void {if(!$value)throw new RuntimeException($message);}
function teams_denied(callable $work,int $status): void {try{$work();}catch(CatalogException $e){teams_ok($e->status===$status,$e->getMessage());return;}throw new RuntimeException('Expected refusal');}
